-- The legal pages move into the store's own settings (store_setting 'legal'), so every store writes its terms and its data
-- policy in the panel and the front shows them on its own pages. The Arisma database keeps the text published on
-- arisma.com.co word for word (the WordPress pages of 2022-03-31); a new store starts with no legal pages.
INSERT INTO store_setting(key, value)
SELECT 'legal', $legal$
{"terms":{"title":"Términos y condiciones de uso","blocks":[{"kind":"heading","text":"TÉRMINOS DE USO"},{"kind":"paragraph","text":"Estimado cliente o usuario, por favor lea con suma atención el siguiente texto. Tenga en cuenta que por el hecho de navegar en esta página Web, usted esta declarando que conoce, acepta y se compromete a cumplir con los términos de uso, condiciones y restricciones que aquí se señalan."},{"kind":"heading","text":"Objeto del sitio:"},{"kind":"paragraph","text":"ARISMA S.A., ha diseñado la presente página Web y sus respectivos minisitios, pensando principalmente en nuestros clientes y usuarios, para su uso, disfrute, entretenimiento, comunicación directa con nosotros, y fácil adquisición de nuestros productos y servicios, por lo tanto, con toda tranquilidad navegue en los sitios que hemos dispuesto para usted, solamente con la excepción de aquellas secciones que su acceso este restringido o limitado y requieran clave que nosotros atribuimos según nuestro criterio."},{"kind":"heading","text":"Aceptación:"},{"kind":"paragraph","text":"Por el hecho de entrar a nuestra página Web, nuestros clientes y usuarios aceptan sin limitación o reserva alguna y declaran haber leído, comprendido y entendido los términos de uso de la misma, los cuales se deberán cumplir a cabalidad y en caso de desear participar en algunos de los concursos, eventos, buzones de sugerencia, entre otros, igualmente se informará y cumplirá las condiciones especiales que tengan los mismos."},{"kind":"paragraph","text":"En el evento que nuestros usuarios o cibernautas no se encuentre de acuerdo con los términos de uso, condiciones y restricciones, se abstendrá inmediatamente de acceder a nuestra página Web."},{"kind":"subheading","text":"Propiedad intelectual"},{"kind":"paragraph","text":"Todo lo que usted observe dentro de nuestra página Web, es de exclusiva titularidad de ARISMA S.A. o excepcionalmente de terceras personas o proveedores que han permitido su uso por parte de ARISMA S.A."},{"kind":"paragraph","text":"Así mismo, todo el material, la información, los bienes y derechos que se encuentran plasmados en la página Web, son protegidos por la propiedad intelectual, los derechos de autor o la propiedad industrial, según corresponda, por lo cual los mismos, solamente se podrán utilizar para los fines mencionados en estos términos de uso, condiciones y restricciones, en consecuencia, NO podrán ser utilizados por los usuarios con fines distintos a los previstos, especialmente con fines de lucro, apropiación, distribución, reutilización, modificación, deformación, mutilación o utilizar el contenido con fines públicos, políticos, comerciales entre otros, sin contar con la respectiva autorización expresa y escrita de ARISMA S.A. o de quien corresponda."},{"kind":"subheading","text":"Información"},{"kind":"paragraph","text":"ARISMA S.A. hace todos los esfuerzos para que la información contenida en la página Web se encuentre debidamente actualizada, no obstante lo anterior, es posible que por periodos breves de tiempo la información contenida en la página, se encuentre desactualizada, presente inexactitudes o tenga errores involuntarios, por lo que no se asumen responsabilidades por los anteriores hechos, por tanto es obligación del usuario que antes de tomar cualquier decisión confirme la veracidad de la misma."},{"kind":"subheading","text":"Responsabilidad"},{"kind":"paragraph","text":"Se considera obligación de los usuarios de la página Web, mantener en funcionamiento y debidamente actualizados diversos mecanismos de protección y seguridad para los dispositivos que emplee para navegar en la página Web y la información que contenga en los mismos, entre los que figuran: Antivirus, firewall, anti-spyware, entre otros. De la misma manera, ARISMA S.A. no se hace responsable por ningún daño, pérdida o perjuicio que pueda sufrir el cibernauta por el uso de la página Web, independientemente de la causa o del efecto generado. En todo caso, cualquier daño, afectación, perjuicio o pérdida de información se presumirá que fue generada por la inexistencia de los mecanismos de protección mencionados."},{"kind":"paragraph","text":"La anterior eximente de responsabilidad y presunción legal, se extenderá a cualquier descarga o copia de imágenes, texto, datos, material, fotografías, video, audio entre otros."},{"kind":"subheading","text":"Confidencialidad"},{"kind":"paragraph","text":"Asegúrese que la información o el material por usted otorgado en la página Web NO sean confidenciales, que usted sea el titular de los mismos o tenga usted derecho a revelarlos sin comprometer su responsabilidad. Toda vez que la información recabada por este medio, por email o similares, no serán objeto de protección especial, independientemente de la información que se trate, entre lo que puede figurar: datos, video, voz, sonido, texto, preguntas, sugerencias o comentarios."},{"kind":"paragraph","text":"La recopilación de los anteriores elementos podrá ser utilizada para la creación de perfiles de usuario, identificación de gastos, preferencias, hábitos de consulta, consumo y actividades desarrolladas en la página Web, desarrollo de nuevos productos, creación de bases de datos, entre otros."},{"kind":"paragraph","text":"La mencionada recopilación, solamente se utilizará para desarrollar labores relacionadas con el objeto social de la compañía y de las empresas relacionadas. Así mismo, ARISMA S.A. entenderá que por habérsele comunicado, la están autorizando a usar la información o material transmitido y podrá sin ninguna responsabilidad o costo, utilizarla independientemente que sean ideas, procedimientos, conceptos, Know How o técnicas, entre otros, toda vez que ARISMA S.A. es una empresa que aprecia mucho la opinión de sus visitantes, sean estos clientes reales o potenciales y la usará siempre que considere que puede representar una mejora en los bienes o servicios prestados."},{"kind":"subheading","text":"Protección especial"},{"kind":"paragraph","text":"Los diseños de los productos, los logos, los slogans, las imágenes de personas o de lugares son de titularidad de ARISMA S.A., por lo tanto está prohibido el uso para fines distintos a los mencionados en estos términos de uso, so pena de incurrir en actuaciones contrarias a las leyes civiles o penales respectivas."},{"kind":"subheading","text":"Signos distintivos"},{"kind":"paragraph","text":"Los signos distintivos ARISMA y cualquier otro exhibido en esta página, es de titularidad de ARISMA S.A. Bajo ningún supuesto se podrá considerar que se permite el uso o se está concediendo una licencia cualquiera que sea su carácter, sobre las marcas, nombres comerciales, enseñas, logos o lemas. Por lo tanto, se considera expresamente prohibido el uso de los mismos, so pena de verse incurso en las responsabilidades civiles y penales a que haya lugar."},{"kind":"subheading","text":"Páginas web relacionadas"},{"kind":"paragraph","text":"ARISMA S.A. ha revisado el contenido sus diferentes dominios relacionados con la página web principal (www.miniarco.com, www.llavesdeaprendizaje.com, www.paletadeaprendizaje.com, www.memory-board.com, www.bornimago.com.co, www.robotica-educativa.com) y se hace responsable de la información expuesta en estos dominios."},{"kind":"paragraph","text":"ARISMA S.A. no ha revisado ni tiene bajo su esfera de dominio otras páginas Web, relacionadas, mencionadas o enlazadas con la Web de su propiedad, por lo que en ningún caso ni bajo ningún supuesto, se generará ni extenderá responsabilidad por la información, los contenidos o el uso que den a la información suministrada por los usuarios a las páginas prenombradas."},{"kind":"subheading","text":"Comunicaciones de los usuarios"},{"kind":"paragraph","text":"Los usuarios de la página Web se comprometen a realizar cualquier tipo de comunicación, transmisiones o remisión de mensajes, de manera respetuosa; sin que los mismos puedan incurrir en mensajes difamatorios, calumniosos, con falsedades, obscenos, pornográficos y en general contrarios a la ley y a las buenas costumbres."},{"kind":"paragraph","text":"ARISMA S.A. no responde por el incumplimiento de la anterior disposición por parte de los usuarios de la página Web."},{"kind":"paragraph","text":"Aunque ARISMA S.A. no tendrá la obligación de revisar detalladamente cada uno de los mensajes, se esforzará por eliminar todos aquellos que incumplan la anterior disposición."},{"kind":"subheading","text":"Independencia de las disposiciones"},{"kind":"paragraph","text":"En el evento que cualquiera de las disposiciones de los términos de uso de la página Web sea declarado nula, inexistente, ineficaz o inoponible por la autoridad competente e independiente del motivo; la validez, legalidad o exigibilidad de las otras disposiciones no se verán afectadas, por lo tanto conservarán toda la fuerza vinculante propia de un contrato."},{"kind":"subheading","text":"Interpretación y revisión"},{"kind":"paragraph","text":"Las disposiciones aquí señaladas se interpretarán de la manera más amplia posible, siendo limitadas únicamente por las leyes imperativas."},{"kind":"paragraph","text":"ARISMA S.A. podrá revisar, modificar, ajustar, actualizar, cambiar e incluso eliminar parcialmente o totalmente en cualquier momento los términos de uso de la página Web, por lo tanto nuestro apreciado cibernauta deberá periódicamente estar consultando esta Web para revisar sus términos de uso."},{"kind":"subheading","text":"Términos de venta y Capacidad para contratar"},{"kind":"paragraph","text":"En cumplimiento de lo dispuesto en las Leyes de Servicios de la Sociedad de la Información y Comercio Electrónico, y demás normativa de aplicación, ARISMA S.A. informa:"},{"kind":"paragraph","text":"Al adquirir los servicios ofertados por ARISMA S.A. el usuario debe tener capacidad para contratar según su ley nacional."},{"kind":"subheading","text":"Objeto del contrato"},{"kind":"paragraph","text":"El contrato tiene por objeto la venta de productos y servicios didácticos. Las características de los mismos aparecen reflejadas en las correspondientes páginas de esta web, siempre en idioma castellano."},{"kind":"paragraph","text":"ARISMA S.A. ofrece las siguientes posibilidades de pago: Tarjeta de crédito, PSE, pago vía Baloto, y pagos referenciados en bancos. Todos estos sistemas ofrecen la máxima seguridad. La entidad bancaria dispone de los medios de seguridad necesarios para identificar posibles errores o fraudes en los datos facilitados al realizar de pago con tarjeta o vía PSE."},{"kind":"subheading","text":"Identificación del proveedor"},{"kind":"paragraph","text":"El proveedor de los productos o servicios contratados por el usuario es ARISMA S.A., con domicilio social en la carrera 15 No. 52A – 14 de la cuidad de Bogotá, Colombia, registrada con el NIT. 860.049.903-8"},{"kind":"paragraph","text":"La cumplimentación y envío del formulario de pedido tiene la consideración de aceptación de los términos del contrato, sin que, en ningún caso, pueda considerarse propuesta comercial."}],"documents":[]},"privacy":{"title":"Política de tratamiento de datos","blocks":[{"kind":"heading","text":"AVISO DE PRIVACIDAD PROTECCIÓN DE DATOS PERSONALES"},{"kind":"paragraph","text":"En cumplimiento a lo estipulado en la Ley 1581 de 2012 y a lo previsto en el Decreto 1377 de 2013, con el objeto de informar a todas las personas cuyos datos personales se encuentran en Nuestras bases de datos tanto físicas como digitalizadas, ARISMA S.A., con domicilio en la Ciudad de Bogotá, Colombia, actúa y es Responsable del Tratamiento de los datos personales."},{"kind":"paragraph","text":"Sus datos personales serán incluidos en una base de datos y el uso y manejo de los mismos se efectúa bajo estrictos estándares de responsabilidad dentro de los cuales está el respeto al debido proceso y a la protección de la información y serán utilizados de manera meramente enunciativa para las siguientes finalidades directas e indirectas relacionadas con el objeto y propósitos de ARISMA S.A."},{"kind":"paragraph","text":"Lograr una eficiente comunicación relacionada con nuestros servicios y demás actividades relacionadas con las funciones propias de ARISMA S.A."},{"kind":"list","items":["Dar cumplimiento a obligaciones contraídas con nuestros pacientes, empleados, clientes y proveedores y cualquier otra persona natural con quien tengamos relación comercial.","Informar sobre cambios en los servicios de ARISMA S.A.","Evaluar la calidad del servicio.","Realizar estudios internos sobre hábitos de consumo de los servicios y productos ofrecidos por ARISMA S.A.","Gestionar cobranzas, emitir estados de cuenta, determinar obligaciones pendientes, consultar información financiera e historia crediticia, y en los casos en que sea requerido, reportar a centrales de información sobre obligaciones incumplidas, respecto de sus deudores.","Firmar y/o ejecutar contratos de suministro y/o prestación de servicios entre ARISMA S.A. y sus proveedores y contratistas.","Informar sobre nuevos servicios que estén relacionados con los ofrecidos o que tenga ARISMA S.A.","Contactar de manera eventual y necesaria, vía correo electrónico, o por cualquier otro medio, a personas naturales con quienes ARISMA S.A. tiene o haya tenido relación jurídica, tales como, pero no se limita a: clientes, proveedores, contratistas, visitantes, acreedores y deudores, para las finalidades antes mencionadas.","Responder a consultas, peticiones, quejas y reclamos realizadas por los titulares.","Transmitir los datos personales a organismos de control y demás autoridades que, en virtud de las leyes concordantes, deban recibir dicha información;","Atender requerimientos judiciales o administrativos, y cumplir mandatos judiciales o legales;","Cualquier otra actividad de naturaleza semejante a las descritas previamente, de carácter ineludible para el desarrollo del objeto social de ARISMA S.A."]}],"documents":[{"title":"Política de tratamiento de datos personales","file":"politica-de-tratamiento-de-datos-personales.pdf"}]}}$legal$::jsonb
WHERE EXISTS (SELECT 1 FROM sales_order WHERE source_key IS NOT NULL)
ON CONFLICT (key) DO NOTHING;
